package app

const appStyle = `
:root{--bg:#0b1020;--sidebar:#10182b;--surface:#151c27;--surface2:#202a36;--line:#344467;--text:#cdd8f5;--muted:#9caed0;--accent:#7aa2f7;--accent-text:#0b1733;--secondary:#7dcfff;--tertiary:#bb9af7;--warm:#e0af68;--glow:#263a70;--input:#111a2e;--note-bg:#1e2d4b;--note-text:#c6d7ff}
body.dracula-dark{--bg:#10131f;--sidebar:#161b2b;--surface:#131722;--surface2:#202638;--line:#44475a;--text:#f2f0f6;--muted:#aaa7b6;--accent:#a897f5;--accent-text:#17181d;--secondary:#8be9fd;--tertiary:#ff79c6;--warm:#f1fa8c;--glow:#221b2d;--input:#101522;--note-bg:#252934;--note-text:#e4d5f6}
body.tomorrow-night{--bg:#0b0d10;--sidebar:#111419;--surface:#12151a;--surface2:#202620;--line:#3a4551;--text:#e2e5e9;--muted:#a3adb9;--accent:#81a2be;--accent-text:#0a121b;--secondary:#b5bd68;--tertiary:#cc99cc;--warm:#f0c674;--glow:#202b36;--input:#12161b;--note-bg:#252e34;--note-text:#d2e0e8}
body.nocturne{--bg:#141019;--sidebar:#1b1726;--surface:#1a1526;--surface2:#242039;--line:#554166;--text:#eee5f6;--muted:#b8a6c8;--accent:#ad8bfa;--accent-text:#1c112a;--secondary:#8db6d9;--tertiary:#d99cbd;--warm:#e6bc9a;--glow:#372444;--input:#1c1525;--note-bg:#35263f;--note-text:#e3cbed}
body.foundry{--bg:#0d1014;--sidebar:#17202a;--surface:#111a21;--surface2:#1c2b31;--line:#465d6c;--text:#e8edf0;--muted:#a4b2ba;--accent:#f0a44c;--accent-text:#1b1510;--secondary:#81a9c4;--tertiary:#70b8a4;--warm:#eac06c;--glow:#3d2d1c;--input:#1c1b19;--note-bg:#352b22;--note-text:#f1d5b5}
*{box-sizing:border-box}html{background:var(--bg)}body{margin:0;background:radial-gradient(ellipse at 78% 0%,var(--glow),transparent 43%),var(--bg);color:var(--text);font:15px/1.55 system-ui,sans-serif;min-height:100vh}.shell{display:grid;grid-template-columns:248px minmax(0,1fr);min-height:100vh}aside{background:var(--sidebar);border-right:1px solid var(--line);padding:18px 14px}.brand{display:flex;align-items:center;gap:10px;padding:7px 8px 20px;font-size:21px;font-weight:800;letter-spacing:.4px}.brand img{width:38px;height:38px;border-radius:9px}.brand span{color:var(--accent)}nav a{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--muted);padding:11px 13px;border-radius:10px;margin:3px 0}nav a:hover,nav a.active{background:color-mix(in srgb,var(--accent) 20%,var(--sidebar));color:var(--text)}nav a.active{border-left:3px solid var(--accent);padding-left:10px}main{padding:30px clamp(20px,4vw,60px);max-width:1450px;width:100%;margin:0 auto}.page-top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:20px}.eyebrow{text-transform:uppercase;letter-spacing:1.8px;color:var(--accent);font-size:11px;font-weight:700}h1{font-size:clamp(28px,3.4vw,42px);line-height:1.15;margin:4px 0 8px;letter-spacing:-1px}h2{font-size:20px;margin:0 0 8px}h3{font-size:16px;margin:0 0 8px}p{color:var(--muted);margin:8px 0 14px}.muted,small{color:var(--muted)}.card{background:linear-gradient(150deg,color-mix(in srgb,var(--surface) 85%,#000),var(--surface));border:1px solid var(--line);border-radius:15px;padding:21px;box-shadow:0 12px 32px #0003}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:18px 0 24px}.metric-card h2{font-size:13px;font-weight:550;color:var(--muted);margin:0 0 7px}.metric{font-size:32px;font-weight:760;color:var(--accent)}.stats .metric-card:nth-child(2) .metric{color:var(--secondary)}.stats .metric-card:nth-child(3) .metric{color:var(--tertiary)}.hero{position:relative;min-height:235px;border:1px solid var(--line);border-radius:18px;overflow:hidden;display:flex;align-items:flex-end;padding:28px;background:#141025}.hero img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.hero:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,#0b0d18ed 0%,#10101caa 52%,#10101c22 100%),linear-gradient(0deg,#0b0d18bb,transparent 65%)}.hero-copy{position:relative;z-index:1;max-width:700px}.hero h1{font-size:clamp(30px,4vw,48px)}.hero p{color:#e0e2fa;max-width:620px}.btn,button{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:1px solid transparent;border-radius:8px;background:var(--accent);color:var(--accent-text);padding:9px 14px;font:inherit;font-size:14px;font-weight:700;text-decoration:none;cursor:pointer}.btn.secondary,button.secondary{background:var(--input);border-color:var(--line);color:var(--text);font-weight:550}.btn.small,button.small{padding:6px 10px;font-size:12px}.btn:hover,button:hover{filter:brightness(1.12)}:focus-visible{outline:2px solid var(--tertiary);outline-offset:3px}label{display:block;color:var(--muted);font-size:13px;margin:12px 0 5px}input,select,textarea{width:100%;min-width:0;background:var(--input);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:10px 12px;font:inherit}textarea{min-height:90px;resize:vertical}input[type=search]{max-width:330px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:2px 16px}.form-grid .wide{grid-column:1/-1}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:14px}.note{padding:12px 15px;border:1px solid var(--line);background:var(--note-bg);border-radius:10px;color:var(--note-text);margin:12px 0}.note.error{border-color:#ba6b82;color:#ffd4dc;background:#40232d}.tabs{display:flex;gap:8px;border-bottom:1px solid var(--line);margin:18px 0}.tabs a{padding:10px 14px;color:var(--muted);text-decoration:none;border-bottom:2px solid transparent}.tabs a.active{color:var(--text);border-color:var(--accent)}.filter-row{display:grid;grid-template-columns:minmax(180px,1fr) repeat(3,minmax(130px,180px)) auto;gap:10px;align-items:end;margin:14px 0}.filter-row label{margin:0}.table-wrap{overflow-x:auto}.table{border-collapse:collapse;width:100%;min-width:750px}.table th,.table td{text-align:left;vertical-align:top;padding:12px 10px;border-bottom:1px solid var(--line)}.table th{color:var(--muted);font-size:12px;font-weight:600}.table td strong{display:block}.badge{display:inline-flex;border:1px solid var(--line);border-radius:999px;padding:3px 8px;color:var(--muted);font-size:11px;white-space:nowrap}.badge.status{color:var(--secondary)}.row-actions{display:flex;gap:7px;flex-wrap:wrap}.row-actions form{margin:0}.table a.external{color:var(--accent);font-size:13px}.table details{margin-top:9px}.table summary{cursor:pointer;color:var(--muted);font-size:12px}.empty{padding:27px;text-align:center;color:var(--muted)}.tracked-preview{margin-top:22px}.tracked-preview .table{min-width:520px}footer{color:var(--muted);font-size:12px;margin:32px 0 10px}.empty-inline{padding:18px 5px;color:var(--muted)}@media(max-width:900px){.shell{grid-template-columns:190px minmax(0,1fr)}aside{padding:14px 9px}.filter-row{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.shell{grid-template-columns:minmax(0,1fr)}main{min-width:0}.table-wrap{min-width:0;max-width:100%}aside{border:0;border-bottom:1px solid var(--line);padding:8px 12px}.brand{padding:5px 6px 8px}.brand img{width:32px;height:32px}nav{display:flex;flex-wrap:wrap}nav a{padding:7px 9px;font-size:12px}main{padding:18px 14px}.stats{grid-template-columns:1fr;gap:10px}.metric-card{padding:15px}.metric{font-size:26px}.hero{min-height:210px;padding:20px}.filter-row,.form-grid{grid-template-columns:1fr}.form-grid .wide{grid-column:auto}.page-top{align-items:flex-start;flex-direction:column}}
/* Build 0.9.1 follow-up: shared page geometry across legacy and campaign templates.
   Keep navigation styling, theme tokens, and icon selection unchanged. */
.shell{min-width:0;grid-template-columns:248px minmax(0,1fr)}
.shell.rail-compact{grid-template-columns:64px minmax(0,1fr)}
.shell>main{box-sizing:border-box;min-width:0;width:100%;max-width:1450px;margin-inline:auto;padding:30px clamp(20px,4vw,60px)}
.shell>main>*{min-width:0;max-width:100%}
.shell>main .grid,.shell>main .stats,.shell>main .filter-row,.shell>main .form-grid{min-width:0;max-width:100%}
.shell>main .grid>*,.shell>main .stats>*,.shell>main .filter-row>*,.shell>main .form-grid>*{min-width:0}
.shell>main img,.shell>main video{max-width:100%}
.shell>main .table-wrap{min-width:0;max-width:100%;overflow-x:auto}
.shell>main .page-top,.shell>main .top{min-width:0;max-width:100%;flex-wrap:wrap}
@media(max-width:900px){.shell:not(.rail-compact){grid-template-columns:190px minmax(0,1fr)}}
@media(max-width:650px){.shell:not(.rail-compact),.shell.rail-compact{grid-template-columns:minmax(0,1fr)}.shell>main{padding:18px 14px}}
`

const campaignPageHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ReelAnvil — Campaigns</title><link rel="icon" type="image/vnd.microsoft.icon" href="/favicon.ico"><style>` + appStyle + `{{.ThemeCSS}}{{.SidebarCSS}}</style></head><body class="{{.BodyTheme}}"><div class="shell">{{.SidebarHTML}}<main><div class="page-top"><div><div class="eyebrow">Campaign workspace</div><h1>Campaigns</h1><p>Track campaigns you choose. Discovery and external enrollment are not connected.</p></div><span class="badge">Local records</span></div><div class="stats"><div class="card metric-card"><h2>Available</h2><div class="metric">{{.Available}}</div><small>Known records not currently tracked</small></div><div class="card metric-card"><h2>Tracked</h2><div class="metric">{{.Tracked}}</div><small>Your local tracking list</small></div><div class="card metric-card"><h2>Ending Soon</h2><div class="metric">{{.EndingSoon}}</div><small>Known deadlines in the next 7 days</small></div></div>{{if .Message}}<div class="note" role="status">{{.Message}}</div>{{end}}{{if .Error}}<div class="note error" role="alert">{{.Error}}</div>{{end}}<div class="card"><h2>Add a campaign manually</h2><p>Adding this record starts local tracking with status Interested. No campaign is applied to or submitted to an external service.</p><details><summary class="btn secondary small">Enter campaign details</summary><form method="post" action="/campaigns/add"><div class="form-grid"><div><label for="platform">Platform</label><select id="platform" name="platform" required>{{range .Platforms}}<option value="{{.ID}}">{{.Name}}</option>{{end}}</select></div><div><label for="campaign-title">Title</label><input id="campaign-title" name="title" required maxlength="160"></div><div class="wide"><label for="campaign-url">Campaign URL</label><input id="campaign-url" name="url" type="url" inputmode="url" placeholder="https://…" required maxlength="2048"></div><div><label for="payout">Payout (optional)</label><input id="payout" name="payout" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" placeholder="Unknown"></div><div><label for="budget">Budget (optional)</label><input id="budget" name="budget" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" placeholder="Unknown"></div><div><label for="deadline">Deadline (optional)</label><input id="deadline" name="deadline" type="date"></div><div><label for="view-url">View campaign URL (optional)</label><input id="view-url" name="view_url" type="url" placeholder="Uses campaign URL when blank"></div><div class="wide"><label for="requirements">Requirements (optional)</label><textarea id="requirements" name="requirements" maxlength="8000"></textarea></div><div><label for="apply-url">Apply / Join URL (optional, verified target)</label><input id="apply-url" name="apply_url" type="url"></div><div><label for="submit-url">Submit content URL (optional, verified target)</label><input id="submit-url" name="submit_url" type="url"></div><div class="wide"><label for="notes">Your notes (optional)</label><textarea id="notes" name="notes" maxlength="8000"></textarea></div></div><div class="actions"><button type="submit">Add and track</button></div></form></details></div><div class="tabs" role="tablist" aria-label="Campaign views"><a role="tab" aria-selected="{{if eq .View "available"}}true{{else}}false{{end}}" class="{{if eq .View "available"}}active{{end}}" href="/campaigns?view=available">Available ({{.Available}})</a><a role="tab" aria-selected="{{if eq .View "tracked"}}true{{else}}false{{end}}" class="{{if eq .View "tracked"}}active{{end}}" href="/campaigns?view=tracked">Tracked ({{.Tracked}})</a></div>{{if eq .View "available"}}<div class="note"><strong>Campaign discovery unavailable.</strong> Public discovery endpoints and permissions have not been independently confirmed for Content Rewards or Vyro. No scraping, login, or authenticated requests are made. You can still add a verified campaign URL manually.</div>{{end}}<form class="filter-row" method="get" action="/campaigns"><input type="hidden" name="view" value="{{.View}}"><div><label for="q">Search</label><input id="q" name="q" type="search" value="{{.Search}}" placeholder="Title or requirements"></div><div><label for="platform-filter">Platform</label><select id="platform-filter" name="platform"><option value="">All platforms</option>{{range .Platforms}}<option value="{{.ID}}" {{if eq $.Platform .ID}}selected{{end}}>{{.Name}}</option>{{end}}</select></div>{{if eq .View "tracked"}}<div><label for="status-filter">Status</label><select id="status-filter" name="status"><option value="">All statuses</option>{{range .Statuses}}<option value="{{.}}" {{if eq $.Status .}}selected{{end}}>{{.}}</option>{{end}}</select></div>{{end}}<div><label for="sort">Sort by</label><select id="sort" name="sort"><option value="title" {{if eq .Sort "title"}}selected{{end}}>Title</option><option value="deadline" {{if eq .Sort "deadline"}}selected{{end}}>Deadline</option><option value="payout" {{if eq .Sort "payout"}}selected{{end}}>Payout</option></select></div><button class="secondary" type="submit">Filter</button></form><div class="card table-wrap"><table class="table"><thead><tr><th>Campaign</th><th>Platform / source</th><th>Status</th><th>Deadline</th><th>Payout / budget</th><th>Actions</th></tr></thead><tbody>{{range .Campaigns}}<tr><td><strong>{{.Title}}</strong><span class="muted">{{if .Requirements}}{{.Requirements}}{{else}}No requirements recorded{{end}}</span>{{if .Notes}}<p><small>Your notes: {{.Notes}}</small></p>{{end}}<details><summary>Source details</summary><p>Provenance: {{.Provenance}}</p><p>Source status: {{if .PlatformStatus}}{{.PlatformStatus}}{{else}}Unknown{{end}}</p><p>Last verified: {{if .VerifiedAt}}{{.VerifiedAt}}{{else}}Not verified{{end}}</p>{{if isManual .}}<details><summary>Edit manually entered campaign</summary>{{ $campaign := .}}<form method="post" action="/campaigns/update"><input type="hidden" name="id" value="{{.ID}}"><input type="hidden" name="tracked" value="{{.Tracked}}"><input type="hidden" name="platform" value="{{.Platform}}"><label>Title</label><input name="title" maxlength="160" required value="{{.Title}}"><label>Campaign URL</label><input name="url" type="url" maxlength="2048" required value="{{.URL}}"><label>Requirements</label><textarea name="requirements" maxlength="8000">{{.Requirements}}</textarea><div class="form-grid"><div><label>Payout</label><input name="payout" inputmode="decimal" value="{{moneyInput .PayoutCents}}"></div><div><label>Budget</label><input name="budget" inputmode="decimal" value="{{moneyInput .BudgetCents}}"></div><div><label>Deadline</label><input name="deadline" type="date" value="{{.Deadline}}"></div>{{if .Tracked}}<div><label>Local status</label><select name="status">{{range $.Statuses}}<option value="{{.}}" {{if eq $campaign.UserStatus .}}selected{{end}}>{{.}}</option>{{end}}</select></div>{{end}}<div><label>View URL</label><input name="view_url" type="url" value="{{.ViewURL}}"></div><div><label>Apply / Join URL</label><input name="apply_url" type="url" value="{{.ApplyURL}}"></div><div><label>Submit content URL</label><input name="submit_url" type="url" value="{{.SubmitURL}}"></div></div>{{if .Tracked}}<label>Your notes</label><textarea name="notes" maxlength="8000">{{.Notes}}</textarea>{{else}}<p>Saving source details keeps this record in Available.</p>{{end}}<button class="secondary small" type="submit">Save campaign</button></form></details>{{end}}</details></td><td>{{platformName .Platform}}<br><span class="badge">{{if isManual .}}Manual{{else}}Discovered{{end}}</span></td><td>{{if .Tracked}}<span class="badge status">{{.UserStatus}}</span><details><summary>Update local status</summary>{{ $campaign := .}}<form method="post" action="/campaigns/status"><input type="hidden" name="id" value="{{.ID}}"><label>Status</label><select name="status">{{range $.Statuses}}<option value="{{.}}" {{if eq $campaign.UserStatus .}}selected{{end}}>{{.}}</option>{{end}}</select><label>Notes</label><textarea name="notes" maxlength="8000">{{.Notes}}</textarea><button class="secondary small" type="submit">Save status</button></form></details>{{else if .PlatformStatus}}<span class="badge">{{.PlatformStatus}}</span>{{else}}<span class="badge">{{if .UserStatus}}Previously {{.UserStatus}}{{else}}Unknown{{end}}</span>{{end}}</td><td>{{deadlineLabel .Deadline}}</td><td>{{money .PayoutCents}}<br><small>Budget: {{money .BudgetCents}}</small></td><td><div class="row-actions"><a class="external" href="{{if .ViewURL}}{{.ViewURL}}{{else}}{{.URL}}{{end}}" target="_blank" rel="noopener noreferrer">View campaign</a>{{if hasValue .ApplyURL}}<a class="external" href="{{.ApplyURL}}" target="_blank" rel="noopener noreferrer">Apply / Join</a>{{end}}{{if hasValue .SubmitURL}}<a class="external" href="{{.SubmitURL}}" target="_blank" rel="noopener noreferrer">Submit content</a>{{end}}<button class="secondary small copy-link" type="button" data-copy="{{.URL}}">Copy Link</button>{{if not .Tracked}}<form method="post" action="/campaigns/track"><input type="hidden" name="id" value="{{.ID}}"><button class="small" type="submit">Track</button></form>{{else}}<form method="post" action="/campaigns/untrack"><input type="hidden" name="id" value="{{.ID}}"><button class="secondary small" type="submit">Untrack</button></form>{{end}}</div></td></tr>{{else}}<tr><td colspan="6" class="empty">{{if eq .View "tracked"}}No tracked campaigns match these filters. Add a campaign manually or track one from Available.{{else}}No available campaign records match these filters. Add a campaign manually to begin tracking.{{end}}</td></tr>{{end}}</tbody></table></div><footer>ReelAnvil · Campaign metadata and tracking are stored locally. Discovery, applying and content submission are not automated.</footer></main></div><script>{{.SidebarScript}}</script><script>document.querySelectorAll('.copy-link').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);const before=b.textContent;b.textContent='Copied';setTimeout(()=>b.textContent=before,1200)}catch(e){b.textContent='Copy unavailable'}}));</script></body></html>`

const overviewPageHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ReelAnvil — Overview</title><link rel="icon" type="image/vnd.microsoft.icon" href="/favicon.ico"><style>` + appStyle + `{{.ThemeCSS}}{{.SidebarCSS}}</style></head><body class="{{.BodyTheme}}"><div class="shell">{{.SidebarHTML}}<main><section class="hero"><img src="/assets/branding/overview-mountain.png" alt="Purple mountain peaks beneath a starry sky reflected in a lake"><div class="hero-copy"><div class="eyebrow">Your campaign workspace</div><h1>Make every frame count.</h1><p>Keep campaign details and deadlines in view. Add and track campaigns manually while platform discovery integrations remain unavailable.</p><a class="btn" href="/campaigns">Open Campaigns</a></div></section><section class="stats" aria-label="Campaign summary"><div class="card metric-card"><h2>Available</h2><div class="metric">{{.Available}}</div><small>Known source records not tracked</small></div><div class="card metric-card"><h2>Tracked</h2><div class="metric">{{.Tracked}}</div><small>Campaigns in your local list</small></div><div class="card metric-card"><h2>Ending Soon</h2><div class="metric">{{.EndingSoon}}</div><small>Known deadlines within 7 days</small></div></section><section class="card tracked-preview"><div class="page-top"><div><div class="eyebrow">Your current list</div><h2>Tracked campaigns</h2></div><a class="btn secondary small" href="/campaigns?view=tracked">View all</a></div>{{if .Campaigns}}<div class="table-wrap"><table class="table"><thead><tr><th>Campaign</th><th>Platform</th><th>Status</th></tr></thead><tbody>{{range .Campaigns}}<tr><td><strong>{{.Title}}</strong><small>{{deadlineLabel .Deadline}}</small></td><td>{{platformName .Platform}}</td><td><span class="badge status">{{.UserStatus}}</span></td></tr>{{end}}</tbody></table></div>{{else}}<div class="empty-inline">No campaigns are tracked yet. Add one manually to get started.</div>{{end}}</section><footer>ReelAnvil · Local-only prototype · No external campaign data is being fetched</footer></main></div><script>{{.SidebarScript}}</script></body></html>`
